WITH deduped AS (SELECT id, page FROM web_events QUALIFY ROW_NUMBER() OVER (PARTITION BY page, session_id ORDER BY duration_sec DESC NULLS FIRST, id) = 1) SELECT page, COUNT(*) FILTER (WHERE page = '/checkout') AS checkout_rows, SIZE(COLLECT_SET(page)) AS num_pages, COUNT(DISTINCT id) AS distinct_ids, COUNT(DISTINCT id) AS distinct_ids_2, COUNT(*) AS cnt, COUNT(*) FILTER (WHERE page = '/home') AS home_rows FROM deduped GROUP BY page ORDER BY home_rows DESC;
